-- =============================================================================
-- 03_views.sql
-- security_invoker views honour the caller's privileges and row-level security,
-- so a student querying them only ever sees their own rows.
-- =============================================================================

-- View 1: section roster with seat availability (no personal data) ----------
CREATE OR REPLACE VIEW v_section_roster AS
SELECT sec.section_id,
       sub.code  AS subject_code,
       sub.title AS subject_title,
       sub.units,
       sec.section_code,
       sec.school_year,
       sec.semester,
       sec.schedule,
       sec.room,
       COALESCE(i.last_name || ', ' || i.first_name, 'TBA') AS instructor,
       sec.capacity,
       COUNT(e.enrollment_id) FILTER (WHERE e.status <> 'dropped')              AS enrolled_count,
       sec.capacity - COUNT(e.enrollment_id) FILTER (WHERE e.status <> 'dropped') AS seats_left
FROM sections sec
JOIN subjects sub            ON sub.subject_id = sec.subject_id
LEFT JOIN instructors i      ON i.instructor_id = sec.instructor_id
LEFT JOIN enrollments e      ON e.section_id = sec.section_id
GROUP BY sec.section_id, sub.subject_id, i.instructor_id;

-- View 2: one row per enrollment with grade and remarks ----------------------
CREATE OR REPLACE VIEW v_student_grades WITH (security_invoker = true) AS
SELECT st.student_id,
       st.student_no,
       st.last_name || ', ' || st.first_name AS student_name,
       e.enrollment_id,
       e.status       AS enrollment_status,
       sub.code       AS subject_code,
       sub.title      AS subject_title,
       sub.units,
       sec.school_year,
       sec.semester,
       g.grade_value,
       CASE
           WHEN g.grade_value IS NULL  THEN 'No grade yet'
           WHEN g.grade_value <= 3.00  THEN 'Passed'
           ELSE 'Failed'
       END AS remarks
FROM enrollments e
JOIN students st  ON st.student_id = e.student_id
JOIN sections sec ON sec.section_id = e.section_id
JOIN subjects sub ON sub.subject_id = sec.subject_id
LEFT JOIN grades g ON g.enrollment_id = e.enrollment_id
WHERE e.status <> 'dropped';

-- View 3: weighted GPA per student (graded subjects only) --------------------
CREATE OR REPLACE VIEW v_student_gpa WITH (security_invoker = true) AS
SELECT st.student_id,
       st.student_no,
       st.last_name || ', ' || st.first_name AS student_name,
       p.code AS program_code,
       COUNT(g.grade_id)                                           AS graded_subjects,
       SUM(sub.units)                                              AS graded_units,
       ROUND(SUM(g.grade_value * sub.units) / NULLIF(SUM(sub.units), 0), 2) AS gpa
FROM students st
JOIN programs p        ON p.program_id = st.program_id
JOIN enrollments e     ON e.student_id = st.student_id
JOIN grades g          ON g.enrollment_id = e.enrollment_id
JOIN sections sec      ON sec.section_id = e.section_id
JOIN subjects sub      ON sub.subject_id = sec.subject_id
GROUP BY st.student_id, p.program_id;

-- View 4: current enrollment load per student --------------------------------
CREATE OR REPLACE VIEW v_student_enrollment_summary WITH (security_invoker = true) AS
SELECT st.student_id,
       st.student_no,
       st.last_name || ', ' || st.first_name AS student_name,
       p.code       AS program_code,
       st.year_level,
       st.status,
       COUNT(e.enrollment_id) FILTER (WHERE e.status = 'enrolled')            AS enrolled_subjects,
       COALESCE(SUM(sub.units) FILTER (WHERE e.status = 'enrolled'), 0)       AS enrolled_units
FROM students st
JOIN programs p         ON p.program_id = st.program_id
LEFT JOIN enrollments e ON e.student_id = st.student_id
LEFT JOIN sections sec  ON sec.section_id = e.section_id
LEFT JOIN subjects sub  ON sub.subject_id = sec.subject_id
GROUP BY st.student_id, p.program_id;


-- =============================================================================
-- 04_procedures.sql
-- A CALL is one atomic transaction: if any RAISE EXCEPTION fires, every change
-- made by the procedure is rolled back automatically. Business-rule failures use
-- the default SQLSTATE P0001 so the application can show the message safely.
-- =============================================================================

-- Procedure 1: enroll a student in a section --------------------------------
CREATE OR REPLACE PROCEDURE sp_enroll_student(p_student_id INTEGER, p_section_id INTEGER)
LANGUAGE plpgsql
AS $$
DECLARE
    v_student_status VARCHAR(20);
    v_capacity       INTEGER;
    v_taken          INTEGER;
    v_existing_id    INTEGER;
    v_existing_stat  VARCHAR(20);
BEGIN
    SELECT status INTO v_student_status FROM students WHERE student_id = p_student_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Student % does not exist.', p_student_id;
    END IF;
    IF v_student_status <> 'active' THEN
        RAISE EXCEPTION 'Student % is % and cannot be enrolled.', p_student_id, v_student_status;
    END IF;

    -- Serialize enrollments per section so two concurrent calls cannot both take the last seat.
    -- (An advisory lock is used because FOR UPDATE would need UPDATE rights on sections.)
    PERFORM pg_advisory_xact_lock(1001, p_section_id);
    SELECT capacity INTO v_capacity FROM sections WHERE section_id = p_section_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Section % does not exist.', p_section_id;
    END IF;

    SELECT enrollment_id, status INTO v_existing_id, v_existing_stat
    FROM enrollments
    WHERE student_id = p_student_id AND section_id = p_section_id;

    IF FOUND AND v_existing_stat <> 'dropped' THEN
        RAISE EXCEPTION 'Student % is already enrolled in section %.', p_student_id, p_section_id;
    END IF;

    SELECT COUNT(*) INTO v_taken
    FROM enrollments
    WHERE section_id = p_section_id AND status <> 'dropped';

    IF v_taken >= v_capacity THEN
        RAISE EXCEPTION 'Section % is full (% of % seats taken).', p_section_id, v_taken, v_capacity;
    END IF;

    IF v_existing_id IS NOT NULL THEN
        UPDATE enrollments SET status = 'enrolled', enrolled_at = now() WHERE enrollment_id = v_existing_id;
    ELSE
        INSERT INTO enrollments (student_id, section_id, status) VALUES (p_student_id, p_section_id, 'enrolled');
    END IF;
END;
$$;

-- Procedure 2: move a student between two sections of the same subject & term.
-- The drop and the new enrollment succeed or fail together.
CREATE OR REPLACE PROCEDURE sp_transfer_section(p_student_id INTEGER, p_from_section INTEGER, p_to_section INTEGER)
LANGUAGE plpgsql
AS $$
DECLARE
    v_from sections%ROWTYPE;
    v_to   sections%ROWTYPE;
BEGIN
    IF p_from_section = p_to_section THEN
        RAISE EXCEPTION 'Source and destination sections are the same.';
    END IF;

    SELECT * INTO v_from FROM sections WHERE section_id = p_from_section;
    IF NOT FOUND THEN RAISE EXCEPTION 'Section % does not exist.', p_from_section; END IF;
    SELECT * INTO v_to   FROM sections WHERE section_id = p_to_section;
    IF NOT FOUND THEN RAISE EXCEPTION 'Section % does not exist.', p_to_section; END IF;

    IF v_from.subject_id <> v_to.subject_id
       OR v_from.school_year <> v_to.school_year
       OR v_from.semester <> v_to.semester THEN
        RAISE EXCEPTION 'Transfers are only allowed between sections of the same subject and term.';
    END IF;

    UPDATE enrollments
    SET status = 'dropped'
    WHERE student_id = p_student_id AND section_id = p_from_section AND status = 'enrolled';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Student % is not currently enrolled in section %.', p_student_id, p_from_section;
    END IF;

    CALL sp_enroll_student(p_student_id, p_to_section);   -- raises (and undoes the drop) if full
END;
$$;


-- =============================================================================
-- 05_triggers.sql
-- Trigger A: generic audit trigger (students, subjects, sections, enrollments,
--            grades, users, announcements) -> audit_log
-- Trigger B: touch students.updated_at
-- Trigger C: block grades for dropped enrollments
-- Trigger D: audit_log is append-only
-- The application sets  app.current_user  per transaction (see app/src/lib/db.ts)
-- so audit rows record who made the change.
-- =============================================================================

CREATE OR REPLACE FUNCTION fn_audit() RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_pk  TEXT := TG_ARGV[0];
    v_row JSONB;
BEGIN
    IF TG_OP = 'DELETE' THEN v_row := to_jsonb(OLD); ELSE v_row := to_jsonb(NEW); END IF;

    INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, changed_by)
    VALUES (
        TG_TABLE_NAME,
        v_row ->> v_pk,
        TG_OP,
        CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) - 'password_hash' END,
        CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) - 'password_hash' END,
        COALESCE(NULLIF(current_setting('app.current_user', true), ''), session_user::text)
    );
    RETURN NULL;
END;
$$;

CREATE TRIGGER trg_audit_students      AFTER INSERT OR UPDATE OR DELETE ON students      FOR EACH ROW EXECUTE FUNCTION fn_audit('student_id');
CREATE TRIGGER trg_audit_subjects      AFTER INSERT OR UPDATE OR DELETE ON subjects      FOR EACH ROW EXECUTE FUNCTION fn_audit('subject_id');
CREATE TRIGGER trg_audit_sections      AFTER INSERT OR UPDATE OR DELETE ON sections      FOR EACH ROW EXECUTE FUNCTION fn_audit('section_id');
CREATE TRIGGER trg_audit_enrollments   AFTER INSERT OR UPDATE OR DELETE ON enrollments   FOR EACH ROW EXECUTE FUNCTION fn_audit('enrollment_id');
CREATE TRIGGER trg_audit_grades        AFTER INSERT OR UPDATE OR DELETE ON grades        FOR EACH ROW EXECUTE FUNCTION fn_audit('grade_id');
CREATE TRIGGER trg_audit_users         AFTER INSERT OR UPDATE OR DELETE ON users         FOR EACH ROW EXECUTE FUNCTION fn_audit('user_id');
CREATE TRIGGER trg_audit_announcements AFTER INSERT OR UPDATE OR DELETE ON announcements FOR EACH ROW EXECUTE FUNCTION fn_audit('announcement_id');

-- Trigger B ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_touch_updated_at() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_students_touch BEFORE UPDATE ON students
FOR EACH ROW EXECUTE FUNCTION fn_touch_updated_at();

-- Trigger C ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_block_grade_for_dropped() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
DECLARE
    v_status VARCHAR(20);
BEGIN
    SELECT status INTO v_status FROM enrollments WHERE enrollment_id = NEW.enrollment_id;
    IF v_status = 'dropped' THEN
        RAISE EXCEPTION 'Cannot record a grade for a dropped enrollment (id %).', NEW.enrollment_id;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_grades_not_dropped BEFORE INSERT OR UPDATE ON grades
FOR EACH ROW EXECUTE FUNCTION fn_block_grade_for_dropped();

-- Trigger D ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_audit_log_immutable() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit_log is append-only; % is not allowed.', TG_OP;
END;
$$;

CREATE TRIGGER trg_audit_log_immutable BEFORE UPDATE OR DELETE ON audit_log
FOR EACH ROW EXECUTE FUNCTION fn_audit_log_immutable();


-- =============================================================================
-- 06_roles.sql - Database security
-- Three NOLOGIN group roles with different access rights, plus row-level
-- security so a student can only read their own records.
--   sis_admin      full control of all SIS objects
--   sis_registrar  manage students, enrollments, grades; read reference data
--   sis_student    read-only, own records + public reference data
-- The application switches to the matching role per request with SET LOCAL ROLE.
-- =============================================================================

-- Roles ---------------------------------------------------------------------
DO $$
DECLARE r TEXT;
BEGIN
    FOREACH r IN ARRAY ARRAY['sis_admin', 'sis_registrar', 'sis_student'] LOOP
        IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
            EXECUTE format('CREATE ROLE %I NOLOGIN', r);
        END IF;
    END LOOP;
END $$;

-- Allow the account that runs this script (and the app connection) to SET ROLE.
GRANT sis_admin, sis_registrar, sis_student TO CURRENT_USER;

-- Start from zero: nobody gets anything by default ---------------------------
REVOKE ALL ON ALL TABLES    IN SCHEMA public FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM PUBLIC;
REVOKE ALL ON ALL PROCEDURES IN SCHEMA public FROM PUBLIC;

-- Supabase auto-exposes the public schema through its REST API to the
-- anon/authenticated roles. Remove their access to our tables entirely.
DO $$
DECLARE r TEXT;
BEGIN
    FOREACH r IN ARRAY ARRAY['anon', 'authenticated'] LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
            EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA public FROM %I', r);
            EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM %I', r);
            EXECUTE format('REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM %I', r);
        END IF;
    END LOOP;
END $$;

GRANT USAGE ON SCHEMA public TO sis_admin, sis_registrar, sis_student;

-- Row-level security (the table owner bypasses it; the roles above do not) ----
ALTER TABLE users         ENABLE ROW LEVEL SECURITY;
ALTER TABLE programs      ENABLE ROW LEVEL SECURITY;
ALTER TABLE instructors   ENABLE ROW LEVEL SECURITY;
ALTER TABLE students      ENABLE ROW LEVEL SECURITY;
ALTER TABLE subjects      ENABLE ROW LEVEL SECURITY;
ALTER TABLE sections      ENABLE ROW LEVEL SECURITY;
ALTER TABLE enrollments   ENABLE ROW LEVEL SECURITY;
ALTER TABLE grades        ENABLE ROW LEVEL SECURITY;
ALTER TABLE announcements ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_log     ENABLE ROW LEVEL SECURITY;

-- The app sets app.student_id for student sessions.
CREATE OR REPLACE FUNCTION fn_current_student_id() RETURNS INTEGER
LANGUAGE sql STABLE AS $$
    SELECT NULLIF(current_setting('app.student_id', true), '')::INTEGER
$$;

-- Policies: staff roles see every row -----------------------------------------
DO $$
DECLARE t TEXT;
BEGIN
    FOREACH t IN ARRAY ARRAY['programs','instructors','students','subjects','sections','enrollments','grades','announcements'] LOOP
        EXECUTE format('CREATE POLICY p_admin_all ON %I FOR ALL TO sis_admin USING (true) WITH CHECK (true)', t);
        EXECUTE format('CREATE POLICY p_registrar_all ON %I FOR ALL TO sis_registrar USING (true) WITH CHECK (true)', t);
    END LOOP;
END $$;
CREATE POLICY p_admin_all ON users     FOR ALL    TO sis_admin USING (true) WITH CHECK (true);
CREATE POLICY p_admin_all ON audit_log FOR ALL    TO sis_admin USING (true) WITH CHECK (true);

-- Policies: students -----------------------------------------------------------
CREATE POLICY p_student_ref_programs    ON programs    FOR SELECT TO sis_student USING (true);
CREATE POLICY p_student_ref_instructors ON instructors FOR SELECT TO sis_student USING (true);
CREATE POLICY p_student_ref_subjects    ON subjects    FOR SELECT TO sis_student USING (true);
CREATE POLICY p_student_ref_sections    ON sections    FOR SELECT TO sis_student USING (true);
CREATE POLICY p_student_own_profile     ON students    FOR SELECT TO sis_student USING (student_id = fn_current_student_id());
CREATE POLICY p_student_own_enrollments ON enrollments FOR SELECT TO sis_student USING (student_id = fn_current_student_id());
CREATE POLICY p_student_own_grades      ON grades      FOR SELECT TO sis_student
    USING (enrollment_id IN (SELECT enrollment_id FROM enrollments WHERE student_id = fn_current_student_id()));
CREATE POLICY p_student_announcements   ON announcements FOR SELECT TO sis_student USING (audience IN ('all', 'students'));

-- Table privileges ---------------------------------------------------------------
-- Admin: everything.
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO sis_admin;
-- audit_log is write-protected for every role: rows are written only by the SECURITY DEFINER
-- trigger function, and the immutability trigger blocks UPDATE/DELETE as well.
REVOKE INSERT, UPDATE, DELETE ON audit_log FROM sis_admin;
GRANT SELECT ON audit_log TO sis_admin;

-- Registrar: day-to-day registrar work, no deletes of students, no user/audit access.
GRANT SELECT                 ON programs, instructors, subjects, sections, announcements TO sis_registrar;
GRANT SELECT, INSERT, UPDATE ON students, enrollments, grades TO sis_registrar;

-- Student: read-only.
GRANT SELECT ON programs, instructors, subjects, sections, announcements,
                students, enrollments, grades TO sis_student;

-- Views
GRANT SELECT ON v_section_roster, v_student_grades, v_student_gpa, v_student_enrollment_summary
    TO sis_admin, sis_registrar, sis_student;

-- Stored procedures: staff only
GRANT EXECUTE ON PROCEDURE sp_enroll_student(INTEGER, INTEGER)           TO sis_admin, sis_registrar;
GRANT EXECUTE ON PROCEDURE sp_transfer_section(INTEGER, INTEGER, INTEGER) TO sis_admin, sis_registrar;
